package com.honorablemobile
import android.net.Uri
import android.app.Activity
import android.content.Intent
import app.honorable.editor.PhotoPresetNamespace
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test
class AudioSaveRequestTest {
 private val unsafe=Class.forName("sun.misc.Unsafe").getDeclaredField("theUnsafe").apply{isAccessible=true}.get(null)as sun.misc.Unsafe
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{set(it,"project",VideoEditProject(5000));set(it,"source",Uri.parse("content://synthetic/video"));set(it,"primaryDurationMs",5000L);set(it,"durationMs",5000);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"workspaceActive",true);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 @Test fun pausedAudioExportReturnsBeforeWidgets(){val a=activity();set(a,"workspaceActive",false);call(a,"saveAudioCopy");assertNull(get(a,"pendingRange"));assertEquals(false,get(a,"importing"))}

 private val destination=Uri.parse("content://synthetic/output")
 @Suppress("UNCHECKED_CAST") private fun request(a:HonorableVideoEditorActivity,code:Int=1000,kind:VideoSaveRequest.Kind=VideoSaveRequest.Kind.AUDIO):VideoSaveRequest {set(a,"pendingRange",0L to 5000L);val p=get(a,"project")as VideoEditProject;return VideoSaveRequest(code,call(a,"closeState")as VideoCloseState,EditorAccessMode.GUEST_BASIC,PhotoPresetNamespace.GUEST,p.segments,p.soundtrack,call(a,"sourceUris")as Map<String,Uri>,call(a,"sourceDurations")as Map<String,Long>,get(a,"importedSources")as Map<String,VideoSource>,kind).also{set(a,"videoSaveRequest",it)}}
 private fun accept(a:HonorableVideoEditorActivity,code:Int=1000,ok:Int=Activity.RESULT_OK,uri:Uri?=destination)=call(a,"acceptVideoSaveResult",code,ok,uri?.let{Intent().setData(it)})
 private fun ready(a:HonorableVideoEditorActivity,code:Int=1000,kind:VideoSaveRequest.Kind=VideoSaveRequest.Kind.AUDIO)=request(a,code,kind).also{set(a,"workspaceActive",false);accept(a,code)}
 @Test fun originalPrimaryConstructorRemainsDefaultVideo(){val a=activity();val p=get(a,"project")as VideoEditProject;val r=VideoSaveRequest(1000,VideoCloseState.capture(p,5000,0,null,null,true,false,"content://synthetic/video"),EditorAccessMode.GUEST_BASIC,PhotoPresetNamespace.GUEST,p.segments,null,mapOf("primary" to Uri.parse("content://synthetic/video")),mapOf("primary" to 5000L),emptyMap());assertEquals(VideoSaveRequest.Kind.VIDEO,r.kind);assertEquals("video/mp4",r.kind.mime);assertEquals("Noble-video-copy.mp4",r.kind.filename)}
 @Test fun audioKindIsReadOnlyWithCorrectMimeAndSuggestedFilename(){val r=request(activity());assertEquals(VideoSaveRequest.Kind.AUDIO,r.kind);assertEquals("audio/mp4",r.kind.mime);assertEquals("Noble-audio-copy.m4a",r.kind.filename);assertFalse(VideoSaveRequest::class.java.methods.any{it.name=="setKind"})}
 @Test fun audioSnapshotKeepsOriginalMusicClipsAndProtectedMaps(){val a=activity();val p=get(a,"project")as VideoEditProject;val music=VideoSoundtrack("content://synthetic/music",10000,loop=false);p.setSoundtrack(music);val r=request(a);val original=r.clips;p.setSoundtrack(null);p.trim(0,1000,3000);assertSame(music,r.music);assertEquals(listOf(VideoSegment(0,5000)),original);assertEquals(5000L,r.durations["primary"]);assertTrue(r.sources.values.contains(Uri.parse("content://synthetic/music")))}
 @Test fun videoAndAudioCodesCannotConsumeEachOther(){val a=activity();val audio=request(a,1000);val video=request(a,1001,VideoSaveRequest.Kind.VIDEO);assertFalse(audio.accept(1001,true,destination));assertFalse(video.accept(1000,true,destination));assertTrue(audio.isPending);assertTrue(video.isPending);assertTrue(audio.accept(1000,true,destination));assertTrue(video.accept(1001,true,destination))}
 @Test fun pausedAudioResultDefersDispatchAndKeepsKind(){val a=activity();val r=ready(a);assertTrue(r.isReady);assertEquals(VideoSaveRequest.Kind.AUDIO,r.kind);assertEquals(false,get(a,"saving"));call(a,"resumeVideoSave");assertTrue(r.isReady);set(a,"workspaceActive",true);assertEquals(true,call(a,"canDispatchVideoSave",r));assertEquals(false,get(a,"importing"))}
 @Test fun changedMusicSourceSessionAndRecoveryRejectAudioBeforeProvider(){for(flag in listOf("music","source","mode","project","recovery","busy")){val a=activity();val r=ready(a);val p=get(a,"project")as VideoEditProject;when(flag){"music"->p.setSoundtrack(VideoSoundtrack("content://synthetic/changed",1000));"source"->set(a,"source",Uri.parse("content://synthetic/other"));"mode"->set(a,"accessMode",EditorAccessMode.ACCOUNT);"project"->set(a,"project",VideoEditProject(5000));"recovery"->set(a,"recoveryBytes",byteArrayOf(1));else->set(a,"draftBusy",true)};set(a,"workspaceActive",true);call(a,"resumeVideoSave");assertTrue(flag,r.isClosed);assertNull(get(a,"videoSaveRequest"));assertEquals(false,get(a,"saving"))}}
 @Test fun audioWritingReleaseClearsOnlyItsEngineReference(){val a=activity();val r=ready(a);r.beginWriting();set(a,"saving",true);val audio=unsafe.allocateInstance(VideoAudioExporter::class.java)as VideoAudioExporter;val video=unsafe.allocateInstance(VideoCompositionExporter::class.java)as VideoCompositionExporter;set(a,"audioExporter",audio);set(a,"exporter",video);assertEquals(true,call(a,"releaseVideoSave",r));assertNull(get(a,"audioExporter"));assertSame(video,get(a,"exporter"));assertEquals(false,get(a,"saving"))}
 @Test fun oldAudioReleaseCannotUnlockNewVideoExport(){val a=activity();val old=ready(a,1000);old.beginWriting();val current=request(a,1001,VideoSaveRequest.Kind.VIDEO);current.accept(1001,true,destination);current.beginWriting();set(a,"saving",true);assertEquals(false,call(a,"releaseVideoSave",old));assertSame(current,get(a,"videoSaveRequest"));assertEquals(true,get(a,"saving"));assertNotNull(get(a,"pendingRange"))}
 @Test fun duplicateAudioResultCannotChangeChosenDestination(){val a=activity();val r=ready(a);accept(a,uri=Uri.parse("content://synthetic/other"));assertSame(r,get(a,"videoSaveRequest"));assertEquals(destination,r.beginWriting());assertNull(r.beginWriting())}
 @Test fun recreationDoesNotPersistAudioDestinationOrRestartEitherWriter(){val a=activity();set(a,"nextVideoSaveCode",1001);ready(a);val state=android.os.Bundle();call(a,"writeVideoSaveState",state);assertEquals(setOf("nextVideoSaveCode","videoSaveRequestCode","videoSaveHadDestination"),state.keySet());val restored=activity();call(restored,"restoreVideoSaveState",state);assertEquals(true,get(restored,"interruptedVideoSave"));assertNull(get(restored,"videoSaveRequest"));assertNull(get(restored,"audioExporter"));assertNull(get(restored,"exporter"));assertEquals(false,get(restored,"saving"))}
 @Test fun soundtrackAndSubtitleOriginalsCannotBeAudioDestinations(){for(original in listOf("content://synthetic/music","content://synthetic/subtitles")){val a=activity();val p=get(a,"project")as VideoEditProject;p.restore(listOf(VideoSegment(0,5000,captions=listOf(VideoCaption(0,500,"Caption")),captionSourceUri="content://synthetic/subtitles")),soundtrack=VideoSoundtrack("content://synthetic/music",10000));val r=request(a);assertTrue(r.accept(1000,true,Uri.parse(original)));assertTrue(r.isClosed);assertNull(r.beginWriting())}}
 @Test fun audioCancellationPreservesAnotherBusyFlag(){val a=activity();val r=request(a);set(a,"workspaceActive",false);set(a,"importing",true);accept(a,ok=Activity.RESULT_CANCELED,uri=null);assertTrue(r.isClosed);assertNull(get(a,"videoSaveRequest"));assertNull(get(a,"pendingRange"));assertEquals(true,get(a,"importing"));assertEquals(false,get(a,"saving"))}
 @Test fun expectedPickerPauseDoesNotCancelAudioRequest(){val a=activity();val r=ready(a);call(a,"invalidateCaptionReviews");assertTrue(r.isReady);assertEquals(VideoSaveRequest.Kind.AUDIO,r.kind);set(a,"workspaceActive",true);assertEquals(true,call(a,"canDispatchVideoSave",r))}
}
